"""Fixed, language-neutral contract vectors; expected values are not generated by the implementation."""

import json
from pathlib import Path

import pytest
import yaml

from cedarkit_query import (
    QueryError,
    load_value,
    normalize_query,
    validate_resource_set,
)

ROOT = Path(__file__).parents[1]


def vectors(name):
    return json.loads((ROOT / "tests/vectors/v1" / (name + ".json")).read_text())


@pytest.mark.parametrize("case", vectors("valid"), ids=lambda c: c["id"])
def test_accept_vectors_in_all_forms(case):
    raw = case["value"]
    expected = load_value(raw, case["kind"])
    assert load_value(json.dumps(raw), case["kind"]) == expected
    assert load_value(yaml.safe_dump(raw), case["kind"]) == expected


@pytest.mark.parametrize("case", vectors("invalid"), ids=lambda c: c["id"])
def test_reject_vectors_in_all_forms(case):
    for value in [
        case["value"],
        json.dumps(case["value"]),
        yaml.safe_dump(case["value"]),
    ]:
        with pytest.raises(QueryError) as e:
            load_value(value, case["kind"])
        assert (e.value.code, e.value.path) == (case["code"], case["path"])


@pytest.mark.parametrize("case", vectors("normalization"), ids=lambda c: c["id"])
def test_normalization_vectors(case):
    assert normalize_query(case["value"]).to_dict() == case["expected"]


def test_examples_are_a_valid_synthetic_resource_combination():
    def read(name):
        return json.loads((ROOT / "examples" / (name + ".json")).read_text())

    resources = validate_resource_set(
        read("parameters"),
        [read("mappings")],
        read("catalog"),
        products=[("example", "orig", "oper-1")],
        interface_contracts={("example.single-field", 1)},
    )
    assert resources.parameter("st(10-40)")["parameter_id"] == "cedarkit.st-10-40"
